      </tr>")).join(''),"</tbody></table>");});const filters="<span><b>Departments:</b> ".concat(depts.length,"</span><span><b>Total Headcount:</b> ").concat(gHead,"</span><span><b>Monthly Cost:</b> PKR ").concat(hrFmtMoney(gCost),"</span><span><b>Generated:</b> ").concat(hrGenLabel(ctx),"</span>");const inner="<div class="rep-secttl">Department Overview</div>
    <table class="rep-tbl"><thead><tr>
      <th>#</th><th>Department</th><th>Description</th>
      <th class="r">Designations</th><th class="r">Headcount</th>
      <th class="r">Monthly Cost</th><th class="r">% of Total</th>
    </tr></thead><tbody>".concat(overviewRows,"</tbody>
    <tfoot>
      <tr class="rep-tot"><td colspan="4">Grand Total</td>
        <td class="r"><b>").concat(gHead,"</b></td><td class="r"><b>").concat(hrFmtMoney(gCost),"</b></td><td class="r">100%</td></tr>
      <tr class="rep-grandtot"><td colspan="5">TOTAL MONTHLY SALARY COST</td>
        <td class="r"><b>PKR ").concat(hrFmtMoney(gCost),"</b></td><td></td></tr>
    </tfoot></table>").concat(detailHTML);return hrBuildReportHTML('Department Summary','Human Resource — Department Summary Report',filters,inner,ctx);}/* ════════ 5. Leave & Attendance Register ════════ */export function generateHrLeaveRegister(ctx){const emps=ctx.emps,getFullName=ctx.getFullName,getDeptName=ctx.getDeptName;const activeEmps=emps.filter(e=>e.status==='Active');const rows=activeEmps.map((e,i)=>{const lv=e.leaves||{};/* Balance = DB ka leaveBalance jab wo asal (>0) ho; warna kul allotted
       (Annual + Casual + Sick). Pehle leaveApiToForm hamesha 0/'' deta tha (kabhi
       undefined nahi), is liye fallback chalta hi nahi tha aur Balance 0 dikhta tha. */const totalAllot=(Number(lv.annual)||0)+(Number(lv.casual)||0)+(Number(lv.sick)||0);const bal=Number(lv.balance)>0?Number(lv.balance):totalAllot;return"<tr><td>".concat(i+1,"</td><td><b>").concat(getFullName(e),"</b></td><td>").concat(e.eid,"</td>
      <td>").concat(getDeptName(e.dId)||'—',"</td><td>").concat(lv.policy||'Standard',"</td>
      <td class="r">").concat(lv.annual||0,"</td><td class="r">").concat(lv.casual||0,"</td>
      <td class="r">").concat(lv.sick||0,"</td><td class="r">").concat(lv.maternity||0,"</td>
      <td class="r"><b>").concat(bal,"</b></td>
      <td>").concat(lv.deductEn?'Yes':'No',"</td>
      <td class="r">").concat(lv.absentDed?'PKR '+hrFmtMoney(lv.absentDed):'—',"</td></tr>");}).join('');const deductCount=activeEmps.filter(e=>e.leaves&&e.leaves.deductEn).length;const filters="<span><b>Active Employees:</b> ".concat(activeEmps.length,"</span><span><b>Deduction Enabled:</b> ").concat(deductCount,"</span><span><b>Generated:</b> ").concat(hrGenLabel(ctx),"</span>");const inner="<div class="rep-secttl">Leave Entitlements & Balances — All Active Employees</div>
    <table class="rep-tbl"><thead><tr>
      <th>#</th><th>Employee Name</th><th>ID</th><th>Department</th><th>Policy</th>
      <th class="r">Annual</th><th class="r">Casual</th><th class="r">Sick</th><th class="r">Maternity</th>
      <th class="r">Balance</th><th>Deduct</th><th class="r">Absent Ded.</th>
    </tr></thead><tbody>".concat(rows,"</tbody></table>");return hrBuildReportHTML('Leave & Attendance Register','Human Resource — Leave & Attendance Register',filters,inner,ctx);}/* ════════ 6. Payroll Summary Report ════════ */export function generateHrPayrollSummary(ctx,monthKey){const emps=ctx.emps,empPayroll=ctx.empPayroll,getFullName=ctx.getFullName,getDeptName=ctx.getDeptName,getDesigName=ctx.getDesigName;const _split3=(monthKey||'2026-05').split('-'),_split4=_slicedToArray(_split3,2),yearVal=_split4[0],monthVal=_split4[1];const MNAMES=['','January','February','March','April','May','June','July','August','September','October','November','December'];const monthName=MNAMES[parseInt(monthVal,10)];const activeEmps=emps.filter(e=>e.status==='Active');let gGross=0,gDed=0,gNet=0,gPaid=0,cPaid=0,cGen=0,cNot=0;const rows=activeEmps.map((e,i)=>{const rec=(empPayroll[e.id]||{})[monthKey]||{};const gross=rec.totalGross||ctx.getEmpTotalGross(e,0);const ded=rec.totalDeductions||ctx.getEmpStdDeductions(e);const net=rec.netPayable||gross-ded;const paid=rec.paidAmount||0;const status=rec.status||'Not Generated';gGross+=gross;gDed+=ded;gNet+=net;gPaid+=paid;if(status==='Paid')cPaid++;else if(status==='Generated'||status==='Partially Paid')cGen++;else cNot++;const sColor=(ctx===null||ctx===void 0?void 0:ctx.style)==='bw'?'#000':status==='Paid'?'#16A34A':status==='Generated'?'#D97706':status==='Partially Paid'?'#0284C7':'#94A3B8';return"<tr>
      <td>".concat(i+1,"</td><td><b>").concat(getFullName(e),"</b></td><td>").concat(e.eid,"</td>
      <td>").concat(getDeptName(e.dId)||'—',"</td><td>").concat(getDesigName(e.desId)||'—',"</td>
      <td class="r">").concat(hrFmtMoney(gross),"</td>
      <td class="r">").concat(hrFmtMoney(ded),"</td>
      <td class="r"><b>").concat(hrFmtMoney(net),"</b></td>
      <td class="r">").concat(hrFmtMoney(paid),"</td>
      <td style="color:").concat(sColor,";font-weight:700">").concat(status,"</td>
    </tr>");}).join('');const filters="<span><b>Period:</b> ".concat(monthName," ").concat(yearVal,"</span><span><b>Total Employees:</b> ").concat(activeEmps.length,"</span><span><b>Paid:</b> ").concat(cPaid,"</span><span><b>Pending:</b> ").concat(cGen+cNot,"</span><span><b>Net Payable:</b> PKR ").concat(hrFmtMoney(gNet),"</span><span><b>Generated:</b> ").concat(hrGenLabel(ctx),"</span>");const inner="
    <div class="rep-secttl">Payroll Summary — ".concat(monthName," ").concat(yearVal,"</div>
    <table class="rep-tbl">
      <thead><tr>
        <th>#</th><th>Employee Name</th><th>ID</th><th>Department</th><th>Designation</th>
        <th class="r">Gross Pay</th><th class="r">Deductions</th><th class="r">Net Payable</th>
        <th class="r">Paid Amount</th><th>Status</th>
      </tr></thead>
      <tbody>").concat(rows,"</tbody>
      <tfoot>
        <tr class="rep-tot">
          <td colspan="5">Grand Totals — ").concat(activeEmps.length," employees</td>
          <td class="r"><b>").concat(hrFmtMoney(gGross),"</b></td>
          <td class="r"><b>").concat(hrFmtMoney(gDed),"</b></td>
          <td class="r"><b>").concat(hrFmtMoney(gNet),"</b></td>
          <td class="r"><b>").concat(hrFmtMoney(gPaid),"</b></td>
          <td></td>
        </tr>
        <tr class="rep-grandtot">
          <td colspan="7">TOTAL NET PAYABLE — ").concat(monthName," ").concat(yearVal,"</td>
          <td class="r"><b>PKR ").concat(hrFmtMoney(gNet),"</b></td>
          <td colspan="2"></td>
        </tr>
      </tfoot>
    </table>");return hrBuildReportHTML("Payroll Summary — ".concat(monthName," ").concat(yearVal),"Human Resource — Payroll Summary \xB7 ".concat(monthName," ").concat(yearVal),filters,inner,ctx);}

