        font-weight:900;
        font-size:14px;
      ">
        SM
      </div>
    `;

  const C = bw
    ? {
        headerBg: '#FFFFFF',
        headerText: '#111111',
        headerMuted: '#4B5563',
        headerKick: '#6B7280',
        divider: '#E5E7EB',

        brand: '#374151',

        filtersBg: '#FFFFFF',
        filtersBorder: '1px solid #D1D5DB',
        filtersText: '#111111',

        secTitle: '#111111',
        secBorder: '#D1D5DB',

        thBg: '#FFFFFF',
        thText: '#111111',
        thBorder: '#D1D5DB',

        tdBorder: '#D1D5DB',
        evenBg: '#FFFFFF',

        totalBg: '#FFFFFF',
        totalBorder: '#111111',

        grandBg: '#FFFFFF',
        grandText: '#111111',

        footerText: '#4B5563',
        footerBorder: '#D1D5DB',
      }
    : {
        headerBg: '#1E3A8A',
        headerText: '#FFFFFF',
        headerMuted: 'rgba(255,255,255,.75)',
        headerKick: 'rgba(255,255,255,.55)',
        divider: 'rgba(255,255,255,.20)',

        brand: '#1E40AF',

        filtersBg: '#EFF6FF',
        filtersBorder: '1px solid #BFDBFE',
        filtersText: '#0F172A',

        secTitle: '#1E40AF',
        secBorder: '#BFDBFE',

        thBg: '#EFF6FF',
        thText: '#0F172A',
        thBorder: '#BFDBFE',

        tdBorder: '#DBEAFE',
        evenBg: '#F8FAFF',

        totalBg: '#EFF6FF',
        totalBorder: '#1E40AF',

        grandBg: '#1E3A8A',
        grandText: '#FFFFFF',

