        }

        /* ==========================
           FIT-TO-PAGE TABLE
           (Employee Directory — every column fits the page width)
           ========================== */

        .rep-tbl.fit {
          table-layout:fixed;
          width:100%;
          font-size:var(--fs, 10px);
        }

        .rep-tbl.fit th,
        .rep-tbl.fit td {
