          size:A4 ${isLandscape ? 'landscape' : 'portrait'};
          margin:6mm;
        }

        @media print {
          * {
            -webkit-print-color-adjust:exact !important;
            print-color-adjust:exact !important;
          }

          html,
          body {
            margin:0;
            padding:0;
          }

          /* Follow the printable area instead of a hard 297mm/210mm width */
          .rep-page {
            width:auto;
            min-width:0;
            min-height:0;
            margin:0;
            padding:0;
            box-shadow:none;
          }

          .rep-header {
            margin-left:0;
            margin-right:0;
          }

          .rep-body {
            padding:14px 0 0;
          }

